"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

import calendar
from dataclasses import dataclass

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"

_DAY_NAMES = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
_MONTH_NAMES = {
    "Jan": 1,
    "Feb": 2,
    "Mar": 3,
    "Apr": 4,
    "May": 5,
    "Jun": 6,
    "Jul": 7,
    "Aug": 8,
    "Sep": 9,
    "Oct": 10,
    "Nov": 11,
    "Dec": 12,
}


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


def _get_header(headers: dict[str, str], name: str) -> str | None:
    lname = name.lower()
    for key, value in headers.items():
        if key.lower() == lname:
            return value
    return None


def _parse_http_date(value: str) -> int:
    s = value.strip()
    if len(s) != 29:
        raise HeaderError(f"not an IMF-fixdate: {value!r}")

    day_name = s[0:3]
    if day_name not in _DAY_NAMES:
        raise HeaderError(f"not an IMF-fixdate: {value!r}")
    if s[3:5] != ", ":
        raise HeaderError(f"not an IMF-fixdate: {value!r}")

    day_str = s[5:7]
    if s[7] != " ":
        raise HeaderError(f"not an IMF-fixdate: {value!r}")
    month_name = s[8:11]
    if s[11] != " ":
        raise HeaderError(f"not an IMF-fixdate: {value!r}")
    year_str = s[12:16]
    if s[16] != " ":
        raise HeaderError(f"not an IMF-fixdate: {value!r}")
    hour_str = s[17:19]
    if s[19] != ":":
        raise HeaderError(f"not an IMF-fixdate: {value!r}")
    minute_str = s[20:22]
    if s[22] != ":":
        raise HeaderError(f"not an IMF-fixdate: {value!r}")
    second_str = s[23:25]
    if s[25:29] != " GMT":
        raise HeaderError(f"not an IMF-fixdate: {value!r}")

    if month_name not in _MONTH_NAMES:
        raise HeaderError(f"not an IMF-fixdate: {value!r}")

    for part in (day_str, year_str, hour_str, minute_str, second_str):
        if not part.isdigit() or not part.isascii():
            raise HeaderError(f"not an IMF-fixdate: {value!r}")

    day = int(day_str)
    month = _MONTH_NAMES[month_name]
    year = int(year_str)
    hour = int(hour_str)
    minute = int(minute_str)
    second = int(second_str)

    if not (1 <= day <= 31 and 0 <= hour <= 23 and 0 <= minute <= 59 and 0 <= second <= 59):
        raise HeaderError(f"not a real date: {value!r}")

    days_in_month = calendar.monthrange(year, month)[1]
    if day > days_in_month:
        raise HeaderError(f"not a real date: {value!r}")

    return calendar.timegm((year, month, day, hour, minute, second, 0, 0, 0))


def _parse_cache_control(value: str | None) -> dict[str, str | None]:
    directives: dict[str, str | None] = {}
    if value is None:
        return directives

    i = 0
    n = len(value)
    while i < n:
        while i < n and value[i] in " \t":
            i += 1
        if i >= n:
            break
        if value[i] == ",":
            i += 1
            continue

        start = i
        while i < n and value[i] not in "=,":
            i += 1
        name = value[start:i].strip()

        directive_value: str | None = None
        if i < n and value[i] == "=":
            i += 1
            while i < n and value[i] in " \t":
                i += 1
            if i < n and value[i] == '"':
                i += 1
                vstart = i
                while i < n and value[i] != '"':
                    i += 1
                directive_value = value[vstart:i]
                if i < n:
                    i += 1
                while i < n and value[i] != ",":
                    i += 1
            else:
                vstart = i
                while i < n and value[i] != ",":
                    i += 1
                directive_value = value[vstart:i].strip()

        if i < n and value[i] == ",":
            i += 1

        if not name:
            continue

        directives[name.lower()] = directive_value

    return directives


def _digits_to_int(value: str | None) -> int | None:
    if value is None:
        return None
    if value != "" and value.isascii() and value.isdigit():
        return int(value)
    return None


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""
    response_cc = _parse_cache_control(_get_header(response_headers, "Cache-Control"))
    request_cc = _parse_cache_control(_get_header(request_headers, "Cache-Control"))

    date_header = _get_header(response_headers, "Date")
    date = _parse_http_date(date_header) if date_header is not None else response_time

    age_header = _get_header(response_headers, "Age")
    age = _digits_to_int(age_header)
    if age is None:
        age = 0

    response_delay = response_time - request_time
    apparent_age = max(0, response_time - date)
    corrected_age = age + response_delay
    initial_age = max(apparent_age, corrected_age)
    resident_time = now - response_time
    current_age = initial_age + resident_time

    s_maxage = _digits_to_int(response_cc.get("s-maxage"))
    max_age = _digits_to_int(response_cc.get("max-age"))

    if s_maxage is not None:
        freshness_lifetime = s_maxage
    elif max_age is not None:
        freshness_lifetime = max_age
    else:
        expires_header = _get_header(response_headers, "Expires")
        last_modified_header = _get_header(response_headers, "Last-Modified")
        if expires_header is not None:
            expires = _parse_http_date(expires_header)
            freshness_lifetime = expires - date
        elif last_modified_header is not None:
            last_modified = _parse_http_date(last_modified_header)
            freshness_lifetime = (date - last_modified) // 10
        else:
            freshness_lifetime = 0

    if freshness_lifetime < 0:
        freshness_lifetime = 0

    request_max_age = _digits_to_int(request_cc.get("max-age"))
    if request_max_age is not None:
        freshness_lifetime = min(freshness_lifetime, request_max_age)

    must_revalidate = (
        "no-store" in response_cc
        or "no-cache" in response_cc
        or "must-revalidate" in response_cc
        or "no-cache" in request_cc
    )

    if must_revalidate:
        verdict = MUST_REVALIDATE
    else:
        min_fresh = _digits_to_int(request_cc.get("min-fresh")) or 0
        if freshness_lifetime > current_age + min_fresh:
            verdict = FRESH
        elif "max-stale" in request_cc:
            max_stale_value = request_cc["max-stale"]
            if max_stale_value is None:
                verdict = FRESH
            else:
                max_stale = _digits_to_int(max_stale_value)
                if max_stale is not None and current_age - freshness_lifetime <= max_stale:
                    verdict = FRESH
                else:
                    verdict = STALE
        else:
            verdict = STALE

    return Result(
        verdict=verdict,
        current_age=current_age,
        freshness_lifetime=freshness_lifetime,
    )
